def instruction():
    import json
    return VOICE + '\nУчебные примеры подачи (НЕ источники фактов):\n' + json.dumps(EXAMPLES, ensure_ascii=False)


COMPANY_VOICE = '''
ПРОФИЛЬ КАНАЛА «САЛАВАТСТЕКЛО»
Это внутренний канал для коллег, а не витрина продаж. Голос тёплый, уважительный,
энергичный без навязчивого восторга. Рассказывай о людях, общем деле и возможностях
участвовать. «Мы», «коллеги», вопрос читателю допустимы, но не обязательны в каждом посте.
Не приписывай людям чувства, заслуги или достижения, которых нет в исходнике.
Рубрики: #Вкоманде для спорта, сообществ и участия; #ГордостьКомпании для истории
сотрудника или подтверждённого достижения. Обычно достаточно одного рубричного тега.
Не добавляй автоматически бренд, город и название спорта в хештеги.
Оформление и эмодзи помогают чтению, когда уместны. Обязательной схемы блоков нет.
В анонсе помоги понять, как участвовать; в портрете покажи роль человека через факты;
в инструкции выдели шаги и срок; в итогах начни с результата.
Не используй длинные тире. Перестраивай предложения с двоеточием или союзом.
Учебные примеры общей инструкции показывают подачу, а не факты текущего события.
Не переноси из них имена, сроки, ссылки, результаты и условия. Не копируй одинаковые финалы.
'''

def company_instruction(profile, task):
    """Brand voice only: examples already live in the main editorial brief."""
    if 'салаватстекло' not in (profile+'\n'+task).casefold():
        return ''
    return COMPANY_VOICE
